mapper.select:
SELECT u.id, u.nickname, u.avatar, u.intro
FROM `user` u
WHERE u.deleted = 0
  AND u.id != #{excludeUserId}
  AND NOT EXISTS (
      SELECT 1 FROM follow f
      WHERE f.user_id = #{excludeUserId} AND f.follow_user_id = u.id AND f.deleted = 0
  )
ORDER BY u.id
LIMIT #{offset}, #{pageSize}
